//! Design tokens for the engine (T01-010). `tokens.rs` is generated by
//! `client/scripts/gen-tokens.ts` from `design/tokens.toml`; colours are sRGB-encoded bytes equal to
//! the CSS hex, and the engine blends in sRGB-encoded space (T02 §4.2, D-BLEND).

#[rustfmt::skip]
mod tokens;
pub use tokens::*;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, serde::Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Theme {
    Dark,
    Light,
}

/// An sRGB-encoded colour with straight alpha.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Rgba8(pub [u8; 4]);

impl Rgba8 {
    /// Each channel / 255; the sRGB values are not linearised (D-BLEND).
    pub fn to_f32(self) -> [f32; 4] {
        [0.0; 4]
    }
}

/// The colour roles the engine draws with.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ColourRole {
    Surface1,
    Hairline,
    TextMuted,
    Brush,
    Text,
}

pub fn colour(theme: Theme, role: ColourRole) -> Rgba8 {
    let _ = (theme, role);
    Rgba8([0; 4])
}
